def solve_tsp(distances: list[list[int]]) -> int:
    n = len(distances)
    if n == 0:
        raise ValueError("Distance matrix cannot be empty.")
    for i in range(n):
        if any(d == float('inf') for d in distances[i]):
            raise ValueError("Distance matrix must contain finite values.")

    def calculate_cost(route: list[int]) -> int:
        total_cost = 0
        for i in range(n - 1):
            total_cost += distances[route[i]][route[i + 1]]
        total_cost += distances[route[-1]][route[0]]  
        return total_cost

    best_cost = float('inf')
    for start_city in range(n):
        visited = [False] * n
        current_route = [start_city]
        visited[start_city] = True
        for _ in range(n - 1):
            min_cost = float('inf')
            next_city = -1
            for city in range(n):
                if not visited[city]:
                    cost = distances[current_route[-1]][city]
                    if cost < min_cost:
                        min_cost = cost
                        next_city = city
            current_route.append(next_city)
            visited[next_city] = True
        best_cost = min(best_cost, calculate_cost(current_route))

    return best_cost 
