    dp = [[float('inf')] * (1 << n) for _ in range(n)]
    dp[0][1] = 0
    for mask in range(1, 1 << n):
        for i in range(n):
            if (mask >> i) & 1:
                for j in range(n):
                    if (mask >> j) & 1 and i != j:
                        dp[i][mask] = min(dp[i][mask], dp[j][mask ^ (1 << i)] + distance_matrix[i][j])
