def solve_shortest_path(distances: dict) -> int:
    graph = defaultdict(dict)
    for u, v, w in distances:
        graph[u][v] = w

    dp = {frozenset([('M', )]): 0}
    for visited in range(1, 5):
        next_dp = {}
        for subset in dp:
            if len(subset) == visited:
