            for u in subset:
                for v in graph[u]:
                    new_subset = set(subset).union({v})
                    if new_subset not in next_dp:
                        next_dp[new_subset] = float('inf')
                    next_dp[new_subset] = min(next_dp[new_subset], dp[subset] + graph[u][v])
        dp = next_dp

    return min(dp.values()) 
