def solve_shortest_path(distances: Dict[tuple, int]) -> int:
    """Finds the shortest total distance to visit all four families.

    Args:
        distances: A dictionary of distances between locations. Keys are tuples representing pairs of locations, and values are the distances between them.

    Returns:
        The shortest total distance to visit all four families.
    """
    locations = ['M', 'A', 'B', 'C', 'D']
    dp = [[float('inf')] * len(locations) for _ in range(len(locations))]
    dp[0][0] = 0  

    for i in range(len(locations)):
        for j in range(len(locations)):
            if i != j:
                dp[i][j] = distances.get((locations[i], locations[j]), float('inf'))

    for k in range(1, len(locations)):
        for i in range(len(locations)):
            for j in range(len(locations)):
                if dp[i][k] != float('inf') and dp[k][j] != float('inf'):
                    dp[i][j] = min(dp[i][j], dp[i][k] + dp[k][j])

    return min(dp[0]) 
