def count_rotor_arrangements(num_slots: int, masses: list[int]) -> int:
    if num_slots != 9 or len(masses) != 9:
        raise ValueError("Invalid input: num_slots must be 9 and masses must have length 9")

    total_mass = sum(masses)
    target_mass_per_group = total_mass // 3

    if total_mass % 3 != 0:
        raise ValueError("Invalid input: Sum of masses must be divisible by 3")

    count = 0
    def is_valid_arrangement(slots: list[int]) -> bool:
        for i in range(0, 9, 3):
            group_mass = sum(slots[i:i+3])
            if group_mass != target_mass_per_group:
                return False
        return True

    def backtrack(index: int, current_arrangement: list[int]):
        nonlocal count
        if index == 9:
            if is_valid_arrangement(current_arrangement):
                count += 1
            return

        for mass in masses:
            if mass not in current_arrangement:
                current_arrangement.append(mass)
                backtrack(index + 1, current_arrangement)
                current_arrangement.pop()

    backtrack(0, [])
    return count  
