def calculate_3430p(n: int) -> float:
    """Calculates the value of 3430 * p, where p is the probability that the sum of numbers in each column of a 3x3 grid is 0."""

    def check_column_sum(grid: List[List[int]]) -> bool:
        for col in range(3):
            if sum(row[col] for row in grid) != 0:
                return False
        return True

    count = 0
    total_combinations = 3**9  # Each cell has 3 possibilities (-1, 0, 1)

    for _ in range(total_combinations):
        grid = [[random.choice([-1, 0, 1]) for _ in range(3)] for _ in range(3)]
        if check_column_sum(grid):
            count += 1

    p = count / total_combinations
