    colors = set()  # Keep track of colors used on adjacent faces
    numbers = set()  # Keep track of numbers used on adjacent faces

    def is_valid(face: int, color: int, number: int) -> bool:
        """Checks if placing a triangle on a face is valid."""
        adjacent_faces = get_adjacent_faces(face)
        for adj_face in adjacent_faces:
            adj_color = colors.get(adj_face, None)
            adj_number = numbers.get(adj_face, None)

            if adj_color is not None and color == adj_color:  # Same color on edge
                return False
            if adj_number is not None and number == adj_number:  # Same number at vertex
                return False
        return True

    def get_adjacent_faces(face: int) -> list[int]:
        """Returns the indices of faces adjacent to a given face."""
        if face in [0, 1, 2, 3]:
            return [face + 4, face + 8]  # Faces sharing an edge
        else:
            return [face - 4, face - 8]

    count = 0
    for i in range(num_faces):
        for color in set(triangles[i]):
            for number in set(triangles[i]):
                if is_valid(i, color, number):
                    colors.add((i, color))
                    numbers.add((i, number))
                    count += 1

    return count



