def is_prime(n: int) -> bool:
    if n <= 1:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def calculate_probability(total_tickets: int, num_tickets_drawn: int) -> float:
    prime_count = sum(1 for i in range(1, total_tickets + 1) if is_prime(i))

    favorable_outcomes = 0
    for combination in combinations(range(1, total_tickets + 1), num_tickets_drawn):
        if sum(combination) % 2 == 0 and sum(1 for x in combination if is_prime(x)) >= 2:
            favorable_outcomes += 1

    return round((favorable_outcomes / combinations(total_tickets, num_tickets_drawn)) * 100, 1)

