def find_min_first_payment(total_debt: float, target_percentage: float, num_months: int, decay_ratio: float) -> int:
    target_amount = total_debt * target_percentage
    remaining_balance = total_debt - target_amount
    monthly_payment = 0
    for month in range(num_months):
        if remaining_balance <= 0:
            break
        monthly_payment = (remaining_balance / (1 - decay_ratio**num_months)) * decay_ratio**(month)
        remaining_balance -= monthly_payment
    return int(monthly_payment)  
