def find_min_first_payment(debt: float, target_percentage: float, months: int, decay_ratio: float) -> int:
    target_amount = debt * target_percentage
    total_paid = 0
    first_payment = 1
    while total_paid < target_amount and months > 0:
        total_paid += first_payment
        first_payment *= decay_ratio
        months -= 1
    if total_paid >= target_amount:
        return int(first_payment)
    else:
        raise ValueError("Unable to reach target percentage within given months.")  
